<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkbench} from '../stores/workbench'
import {blockingReasons} from '../lib/domain'
import {agentApi,type AgentRun,type Readiness} from '../lib/agent-api'
import Icon from '../components/Icon.vue'
const store=useWorkbench(),route=useRoute(),router=useRouter()
const readiness=ref<Readiness>({online:false,liveModelsEnabled:false}),runs=ref<AgentRun[]>([]),selected=ref<AgentRun>(),error=ref(''),busy=ref(false),deleted=ref(false),mode=ref<'FIXTURE'|'LIVE'>('FIXTURE')
const projectId=ref(String(route.query.projectId??'')),nodeId=ref(String(route.query.node??'N08'))
const consultationRoles=ref<string[]>([])
const project=computed(()=>store.state.projects.find(p=>p.id===projectId.value)),node=computed(()=>store.catalog.nodes.find(n=>n.id===nodeId.value))
const availableConsultants=computed(()=>store.catalog.agents.filter(a=>a.id!==node.value?.agentRole))
const currentProfile=computed(()=>readiness.value.profiles?.find(p=>p.id===node.value?.agentRole))
const availableTools=computed(()=>currentProfile.value?.availableTools?.[mode.value]??[])
const unavailableTools=computed(()=>(currentProfile.value?.declaredTools??[]).filter(name=>!availableTools.value.includes(name)))
const reasons=computed(()=>store.connection==='local'?['当前使用浏览器本地工作区，请先备份本地数据并刷新页面连接本机服务，再启动协作']:project.value&&node.value?blockingReasons(project.value,node.value,store.catalog):[])
const filtered=computed(()=>runs.value.filter(r=>!!r.deletedAt===deleted.value&&(!projectId.value||r.projectId===projectId.value)))
const statusNames:Record<string,string>={PENDING_SUBMISSION:'等待投递',SUBMITTED:'已投递',QUEUED:'排队中',RUNNING:'协作中',WAITING_ACCEPTANCE:'等你采纳',ACCEPT_PENDING_SYNC:'草稿已保存 · 同步中',ADOPTED:'已采纳为草稿',ACCEPTED:'已采纳',REJECT_PENDING_SYNC:'拒绝同步中',REJECTED:'已拒绝',CANCEL_PENDING_SYNC:'取消同步中',CANCEL_SYNC_FAILED:'取消结果未确认',CANCELLED:'已取消',FAILED:'执行失败',UNKNOWN:'结果未知 · 需核对',REWORK_EXHAUSTED:'返工次数已用完',SUBMISSION_FAILED:'投递失败 · 需处理',ADOPTED_SYNC_FAILED:'草稿已保存 · 检查点同步失败',REJECTED_SYNC_FAILED:'拒绝已记录 · 检查点同步失败'}
const eventNames:Record<string,string>={RUN_CREATED:'保存任务与输入快照',SUPERVISOR_STARTED:'主管安排专家',AGENT_STARTED:'独立 Agent 开始',AGENT_FINISHED:'独立 Agent 交付',MODEL_STARTED:'模型推理开始',MODEL_FINISHED:'模型推理结束',TOOL_STARTED:'调用工具',TOOL_FINISHED:'工具返回',CONSULTATION_FINISHED:'会诊意见已交接',CONSULTATION_COMPARISON_INCOMPLETE:'意见对照待人工核对',CANDIDATE_CREATED:'保存候选版本',REVIEW_FINISHED:'评审交接',HUMAN_ACCEPTANCE_REQUIRED:'等待人工采纳',ACCEPTED:'采纳完成',REJECTED:'候选已拒绝',CANCELLED:'任务已取消',EXECUTION_FAILED:'执行中止',RECOVERY_UNKNOWN:'中断后的结果待核对'}
const selectedStatus=computed(()=>selected.value?statusNames[selected.value.state.startsWith('ACCEPT')||['ADOPTED','REJECTED','REJECT_PENDING_SYNC','CANCEL_PENDING_SYNC','CANCEL_SYNC_FAILED','CANCELLED','SUBMISSION_FAILED','ADOPTED_SYNC_FAILED','REJECTED_SYNC_FAILED'].includes(selected.value.state)?selected.value.state:selected.value.runtime?.status??selected.value.state]??selected.value.state:'')
const artifacts=computed(()=>selected.value?.runtime?.artifacts??[]),candidate=computed(()=>artifacts.value.filter(a=>a.kind==='CANDIDATE').at(-1)?.content)
const canDecide=computed(()=>store.connection==='server'&&!selected.value?.deletedAt&&selected.value?.state==='SUBMITTED'&&selected.value.runtime?.status==='WAITING_ACCEPTANCE')
let timer:ReturnType<typeof setInterval>,polling=false,stopped=false
async function refresh(_manual=false){if(polling)return;polling=true;let baseLoaded=false;try{const [ready,list]=await Promise.all([agentApi<Readiness>('/readiness'),agentApi<AgentRun[]>()]);if(stopped)return;baseLoaded=true;readiness.value=ready;runs.value=list;const id=String(route.query.run??selected.value?.id??'');if(id){const detail=await agentApi<AgentRun>('/'+id);if(!stopped&&String(route.query.run??selected.value?.id??'')===id)selected.value=detail}error.value=''}catch(e){if(stopped)return;const message=e instanceof Error?e.message:'连接失败';if(!baseLoaded)readiness.value={...readiness.value,online:false,liveModelsEnabled:false,message:'协作运行服务连接失败，请检查服务后重试。'};error.value=message}finally{polling=false}}
async function choose(run:AgentRun){selected.value=run;await router.replace({query:{...route.query,run:run.id}});await refresh(true)}
async function start(){if(store.connection!=='server'||!project.value||!node.value)return;busy.value=true;error.value='';try{const run=await agentApi<AgentRun>('',{id:'run_'+crypto.randomUUID(),projectId:project.value.id,nodeId:node.value.id,mode:mode.value,consultationRoles:consultationRoles.value});await choose(run);store.toast(mode.value==='FIXTURE'?'已创建测试运行：不会调用付费模型':'已创建真实模型运行，将按授权配置调用')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function decide(decision:string){if(!selected.value||!canDecide.value)return;busy.value=true;try{await agentApi('/'+selected.value.id+'/decision',{decision});if(decision==='ACCEPT'){const refreshed=await store.init();store.toast(refreshed?'候选已保存为草稿，请核对后再标记完成':'候选已保存，但工作区刷新失败；请检查连接后刷新页面',refreshed?'success':'error')}await refresh(true)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function control(action:string){if(!selected.value)return;busy.value=true;try{await agentApi('/'+selected.value.id+'/control',{action});await refresh(true)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function roleName(role:string){return role==='SUPERVISOR'?'主管':role==='REVIEWER'?'独立评审':store.catalog.agents.find(a=>a.id===role)?.name??'系统'}
watch(nodeId,()=>{consultationRoles.value=[]})
watch(()=>route.query.run,()=>{refresh()})
onMounted(()=>{refresh(true);timer=setInterval(()=>{if(!document.hidden)refresh()},2500)})
onUnmounted(()=>{stopped=true;clearInterval(timer)})
</script>
<template><div class="page-content agent-runs-page"><div class="page-heading"><div><span class="eyebrow">真实委派 · 独立评审 · 人工采纳</span><h1>看见团队如何工作</h1><p>每一版候选，都有执行记录和交接依据。</p></div><button class="btn" @click="refresh(true)"><Icon name="RotateCcw" :size="15"/>刷新状态</button></div>
 <div class="run-readiness"><span :class="['badge',readiness.online?'success':'warning']">{{readiness.online?'协作运行服务已连接':'运行服务未连接'}}</span><span>LangGraph + Deep Agents</span><span>真实模型：{{readiness.liveModelsEnabled?'已由操作者开启':'关闭'}}</span><RouterLink class="text-link" to="/models">配置全局与专家模型<Icon name="ArrowUpRight" :size="14"/></RouterLink></div>
 <div v-if="!readiness.online" class="info-strip"><Icon name="Info"/>{{readiness.message??'请使用 scripts/start-local.ps1 启动三个本机服务。'}}</div>
 <form class="run-launch" @submit.prevent="start"><div><h2>开始一次节点协作</h2><p>{{mode==='FIXTURE'?'测试产物带有标识，只验证执行链路。':'真实调用使用固定模型快照和运行上限，费用以供应商账单为准。'}}</p></div><label>作品<select v-model="projectId" required><option value="">选择作品</option><option v-for="p in store.state.projects" :value="p.id" :key="p.id">{{p.title}}{{p.sample?' · 示例':''}}</option></select></label><label>节点<select v-model="nodeId"><option v-for="n in store.catalog.nodes" :key="n.id" :value="n.id">{{n.id}} {{n.name}}</option></select></label><label>运行模型<select v-model="mode"><option value="FIXTURE">测试模型 · 无费用</option><option value="LIVE" :disabled="!readiness.liveModelsEnabled">真实模型{{readiness.liveModelsEnabled?' · 需授权白名单':' · 尚未开启'}}</option></select></label><button class="btn primary" :disabled="busy||!project||!readiness.online||!!reasons.length"><Icon name="Play" :size="15"/>{{mode==='FIXTURE'?'启动测试协作':'启动模型协作'}}</button><div class="consultation-options"><fieldset><legend>会诊专家（{{consultationRoles.length}} / 6）</legend><div class="consultant-grid"><label v-for="a in availableConsultants" :key="a.id"><input v-model="consultationRoles" type="checkbox" :value="a.id" :disabled="consultationRoles.length>=6&&!consultationRoles.includes(a.id)">{{a.name}}</label></div></fieldset><p>可选，最多六位，按勾选顺序串行执行，各自继承角色模型。共享调用次数和时间上限，人数增加或返工可能耗尽预算并产生额外费用。</p></div><p v-if="reasons.length" class="run-blocking">{{reasons.join('；')}}</p><p v-else-if="node" class="run-blocking">{{store.catalog.agents.find(a=>a.id===node?.agentRole)?.name}}负责交付；主管、专家、评审分别运行。模型配置在任务开始时固定。</p></form>
 <div v-if="readiness.online&&currentProfile?.availableTools" class="info-strip"><Icon name="Info"/><span>当前{{mode==='LIVE'?'真实':'测试'}}模式可用工具：{{availableTools.length?availableTools.join('、'):'当前模式未启用'}}。<template v-if="unavailableTools.length"> 已声明但当前不可用：{{unavailableTools.join('、')}}。</template>实际来源及服务仍需调用时核验。</span></div>
 <div v-if="error" role="alert" class="run-error">{{error}}</div>
 <div class="run-layout"><section class="run-inbox"><div class="section-heading"><h2>运行记录</h2><button class="text-link" @click="deleted=!deleted">{{deleted?'返回运行列表':'已删除'}}</button></div><button v-for="r in filtered" :key="r.id" :class="['run-card',{selected:selected?.id===r.id}]" @click="choose(r)"><div><b>{{r.nodeId}} · {{store.catalog.nodes.find(n=>n.id===r.nodeId)?.name}}</b><span class="badge neutral">{{r.mode==='FIXTURE'?'测试模型':'真实模型'}}</span></div><p>{{store.state.projects.find(p=>p.id===r.projectId)?.title}}</p><small>{{new Date(r.createdAt).toLocaleString('zh-CN')}}</small><span v-if="selected?.id===r.id" class="run-card-state">{{selectedStatus}}</span></button><div v-if="!filtered.length" class="empty-state"><Icon name="GitBranch" :size="32"/><h3>{{deleted?'没有已删除运行':'等待第一条协作记录'}}</h3><p>选择作品与可执行节点，启动一次测试。</p></div></section>
 <section v-if="selected" class="run-detail"><div class="run-detail-heading"><div><small>{{selected.nodeId}} · {{selected.executionMode==='PLAN_ONLY'?'制作方案，尚未执行外部工具':'文字候选'}}</small><h2>{{selectedStatus}}</h2></div><div class="heading-actions"><button v-if="selected.deletedAt" class="btn" @click="control('RESTORE')">恢复记录</button><template v-else><button v-if="['SUBMISSION_FAILED','ADOPTED_SYNC_FAILED','REJECTED_SYNC_FAILED','CANCEL_SYNC_FAILED'].includes(selected.state)" class="btn" :disabled="busy" @click="control('RETRY')">{{selected.state==='CANCEL_SYNC_FAILED'?'重试取消':'重试投递'}}</button><button v-if="selected.state==='SUBMISSION_FAILED'||(['PENDING_SUBMISSION','SUBMITTED'].includes(selected.state)&&(!selected.runtime||['QUEUED','RUNNING','WAITING_ACCEPTANCE'].includes(selected.runtime.status)))" class="btn" :disabled="busy" @click="control('CANCEL')">取消运行</button><button class="icon-btn danger-text" aria-label="删除运行记录" :disabled="busy||['SUBMISSION_FAILED','CANCEL_PENDING_SYNC','CANCEL_SYNC_FAILED'].includes(selected.state)" @click="control('DELETE')"><Icon name="Trash2" :size="16"/></button></template></div></div>
  <p v-if="selected.runtimeMessage" class="run-error">{{selected.runtimeMessage}}</p><p v-if="selected.runtime?.error" class="run-error">{{selected.runtime.error}}</p><p v-if="selected.dispatchError" class="run-error">最近投递失败：{{selected.dispatchError}}（已尝试 {{selected.dispatchAttempts??0}} 次，可重试投递）</p><p v-if="selected.state==='SUBMISSION_FAILED'" class="run-error">请求可能已经到达远端；取消需要确认远端状态。</p><div class="run-contract"><span>{{selected.mode==='FIXTURE'?'测试模型 · 0 次外部模型调用':'真实模型 · 费用以供应商账单为准'}}</span><span>上限 {{selected.limits.maxModelCalls}} 次推理 · {{selected.limits.maxReworks}} 次返工</span><span>输入快照 {{selected.id.slice(-8)}}</span></div>
  <p v-if="selected.consultationRoles?.length" class="run-consultants">会诊：{{selected.consultationRoles.map(roleName).join('、')}}</p><details class="run-model-snapshot"><summary>查看模型配置快照</summary><p v-for="(model,key) in selected.models" :key="key">{{key==='worker'?'专家':key==='supervisor'?'主管':key==='reviewer'?'评审':key.startsWith('consultant_')?'会诊 · '+roleName(key.slice(11)):key}}：{{model.name??'未配置'}}{{selected.mode==='FIXTURE'?'（本次实际使用测试模型）':''}}</p></details><div v-if="candidate" class="candidate-panel"><div class="section-heading"><h3>第 {{candidate.version}} 版候选</h3><span class="badge warning">{{candidate.fixture?'测试产物 · 请勿发布':'待核对'}}</span></div><pre>{{candidate.body}}</pre><details><summary>结构化交付、来源与不确定性</summary><pre>{{JSON.stringify(candidate.fields,null,2)}}</pre><div v-if="candidate.sources?.length" class="candidate-sources"><b>来源</b><ul><li v-for="source in candidate.sources" :key="source">{{source}}</li></ul></div><p v-for="u in candidate.uncertainties" :key="u">{{u}}</p></details><details v-if="candidate.consultations?.length"><summary>查看会诊意见</summary><div v-for="opinion in candidate.consultations" :key="opinion.role"><h4>{{roleName(opinion.role)}}</h4><pre>{{opinion.analysis}}</pre><p v-for="source in opinion.sources" :key="source">来源：{{source}}</p><p v-for="uncertainty in opinion.uncertainties" :key="uncertainty">待核实：{{uncertainty}}</p></div></details><details v-if="candidate.consultationComparison"><summary>查看会诊意见对照</summary><p>{{candidate.consultationComparison.summary}}</p><p>{{candidate.consultationComparison.notice}}</p><p v-if="candidate.consultationComparison.status!=='NEEDS_REVIEW'&&!candidate.consultationComparison.differences.length">未列出分歧；请结合原始意见核对。</p><div v-for="(difference,index) in candidate.consultationComparison.differences" :key="index"><h4>{{difference.topic}}</h4><p v-for="position in difference.positions" :key="position.role"><b>{{roleName(position.role)}}：</b>「{{position.quote}}」<small> · 原意见 {{position.opinionHash.slice(0,12)}}</small></p></div></details><div class="candidate-review" v-for="a in artifacts.filter(a=>a.kind==='REVIEW')" :key="a.version"><span :class="['badge',a.content.verdict==='PASS'?'success':'warning']">第 {{a.version}} 版 {{a.content.verdict==='PASS'?'评审通过':'要求返工'}}</span><p>{{a.content.summary}} {{a.content.issues?.join('；')}}</p></div><div v-if="canDecide" class="candidate-actions"><p>采纳会写入节点草稿。核对真实事实与文件后，在作品中标记完成。</p><button class="btn" :disabled="busy" @click="decide('REJECT')">拒绝候选</button><button class="btn primary" :disabled="busy" @click="decide('ACCEPT')">采纳为草稿<Icon name="ArrowRight" :size="14"/></button></div><RouterLink :to="'/projects/'+selected.projectId+'?node='+selected.nodeId" class="text-link">打开对应作品节点<Icon name="ArrowUpRight" :size="14"/></RouterLink></div>
  <div class="run-timeline"><h3>执行与交接记录</h3><ol><li v-for="e in selected.events" :key="e.seq" :class="{handoff:['AGENT_STARTED','REVIEW_FINISHED','TOOL_STARTED'].includes(e.kind)}"><span class="timeline-dot"/><div><b>{{eventNames[e.kind]??e.kind}}</b><small>{{roleName(e.role)}} · {{new Date(e.at).toLocaleTimeString('zh-CN')}}</small><p v-if="e.data.tool">{{e.data.tool}}{{e.data.delegate?' → '+roleName(String(e.data.delegate)):''}}</p><p v-if="e.data.verdict">{{e.data.verdict==='REVISE'?'退回专家返工':'通过，交给人工采纳'}}</p><p v-if="e.data.profileHash">专家配置已固定 · {{String(e.data.profileHash).slice(0,12)}}</p></div><code>#{{e.seq}}</code></li></ol><p v-if="!selected.events?.length" class="muted">任务意图已保存，等待运行服务接收。</p></div>
 </section><section v-else class="run-detail run-empty"><Icon name="Workflow" :size="42"/><h2>每一步协作，都有迹可循</h2><p>左侧选择运行，查看主管委派、专家工具调用、评审返工和候选版本。</p><a class="text-link" href="/guides/agent-runtime.md" target="_blank" rel="noopener">查看实现与能力边界<Icon name="ArrowUpRight" :size="14"/></a></section></div>
</div></template>

<style scoped>
.run-readiness{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:18px 0;color:var(--text-muted,#777);font-size:12px;border-top:1px solid #e5e3de}.run-readiness .text-link{margin-left:auto}.run-launch{display:grid;grid-template-columns:1.1fr 1fr 1fr .7fr auto;gap:18px;align-items:end;background:#fff;border:1px solid #e5e3de;padding:22px;border-radius:14px;margin:12px 0 24px}.run-launch h2{font-size:17px;margin:0 0 8px}.run-launch p{color:#777;font-size:12px;line-height:1.7}.run-launch label{display:grid;gap:8px;font-size:12px}.run-launch select{width:100%;min-width:0;padding:10px;border:1px solid #dddcd6;border-radius:6px;background:#fafaf8}.run-blocking{grid-column:1/-1;margin:0!important}.consultation-options{grid-column:1/-1;display:grid;gap:12px}.consultation-options fieldset{min-width:0;border:0;padding:0;margin:0}.consultation-options legend{font-size:12px;margin-bottom:8px}.consultant-grid{display:flex;flex-wrap:wrap;gap:8px 16px}.consultation-options .consultant-grid label{display:flex;align-items:center;gap:5px}.consultation-options p{margin:0}.run-consultants{font-size:12px;color:#596658}@media(max-width:800px){.consultation-options{grid-template-columns:1fr}}.run-model-snapshot{font-size:12px;color:#7c8575;padding:16px 0;border-bottom:1px solid #efeee9}.run-model-snapshot summary{cursor:pointer}.run-model-snapshot p{font-size:11px}.run-error{padding:14px 18px;background:#fff2ed;color:#a04428;border-radius:8px;margin:14px 0;font-size:13px}.run-layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:24px;align-items:start}.run-inbox .section-heading{margin-bottom:14px}.run-card{display:block;width:100%;padding:18px;text-align:left;background:#fff;border:1px solid #e6e4df;border-radius:10px;margin-bottom:10px;cursor:pointer;transition:transform .2s,border-color .2s}.run-card:hover{transform:translateY(-2px)}.run-card.selected{border-color:#4f624f;background:#f5f7f2}.run-card>div{display:flex;justify-content:space-between;gap:10px;align-items:center}.run-card b{font-size:13px}.run-card p{font-size:12px;color:#6f756d;margin:10px 0}.run-card small{font-size:10px;color:#92958e}.run-card-state{display:block;font-size:12px;margin-top:12px;color:#476344}.run-detail{background:#fff;border:1px solid #e6e4df;border-radius:14px;padding:26px;min-width:0}.run-detail-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.run-detail-heading small{font-size:12px;color:#81867b}.run-detail-heading h2{font-size:24px;margin:8px 0 0}.run-contract{display:flex;flex-wrap:wrap;gap:12px;padding:18px 0;border-bottom:1px solid #efeee9;font-size:10px;color:#93958c}.candidate-panel{padding:24px 0;border-bottom:1px solid #efeee9}.candidate-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-family:inherit;font-size:13px;background:#f8f8f4;padding:18px;border-radius:8px}.candidate-panel summary{font-size:12px;cursor:pointer;padding:8px 0}.candidate-panel details p{font-size:12px;color:#777}.candidate-review{display:flex;gap:10px;align-items:center;margin:12px 0}.candidate-review p{font-size:11px;color:#888}.candidate-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;align-items:center;margin:20px 0}.candidate-actions p{flex:1 1 100%;font-size:12px;color:#6d7768;margin:0}.run-timeline{padding-top:24px}.run-timeline h3,.candidate-panel h3{font-size:15px}.run-timeline ol{list-style:none;padding:0;margin:24px 0 0}.run-timeline li{position:relative;display:flex;justify-content:space-between;gap:12px;border-left:1px solid #e7e9e1;margin-left:5px;padding:0 0 20px 22px}.timeline-dot{position:absolute;width:7px;height:7px;border-radius:50%;background:#c4cbbd;left:-4px;top:4px;box-shadow:0 0 0 4px white}.handoff .timeline-dot{background:#5d7654}.run-timeline b{display:block;font-size:12px;font-weight:500}.run-timeline small{display:block;font-size:10px;color:#8c9386;margin-top:5px}.run-timeline p{font-size:11px;color:#6b7e63;margin:6px 0 0}.run-timeline code{font-size:10px;color:#afb5a8}.run-empty{display:flex;min-height:400px;flex-direction:column;align-items:center;justify-content:center;color:#7d8974;text-align:center}.run-empty h2{font-size:22px;color:#45513f;margin-top:24px}.run-empty p{max-width:360px;font-size:13px;line-height:1.8}.run-empty .text-link{margin-top:20px}@media(max-width:1200px){.run-launch{grid-template-columns:1fr 1fr}.run-layout{grid-template-columns:260px minmax(0,1fr)}}@media(max-width:800px){.run-layout,.run-launch{grid-template-columns:1fr}.run-detail{padding:18px}.run-readiness{gap:10px}.run-card{padding:14px}.run-detail-heading{align-items:flex-start}.candidate-review{align-items:flex-start;flex-direction:column}}@media(prefers-reduced-motion:reduce){.run-card{transition:none}.run-card:hover{transform:none}}
</style>
